function beginLearning(which){subject=which;mode=which;round=0;openModal(which==='math'?'Skybridge':'Wordforge',which==='math'?'RESTORE THE PATH TO THE OBSERVATORY':'WORDS LIGHT UP THE WORLD');nextQuestion();}
