let activePointerGuard=null;let letter='A',lower=false,tracePaths=[],tracing=false;function trace(){mode='trace';openModal('Letter Trails','FINGER & APPLE PENCIL PLAY');$('modal-body').innerHTML=`<div class="trace-area"><div class="subject-row"><span class="draw-title">Follow the trail. Make your own mark.</span><button class="small-btn" data-action="finger-input">Enable finger drawing</button><button class="secondary" data-action="letter-case">${lower?'lowercase → UPPERCASE':'UPPERCASE → lowercase'}</button></div><canvas id="trace-canvas" class="trace-canvas" tabindex="0" aria-label="Letter drawing pad"></canvas><div class="alphabet">${'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('').map(l=>`<button data-action="letter" data-letter="${l}" class="${l===letter?'selected':''}">${lower?l.toLowerCase():l}</button>`).join('')}</div><div class="learn-controls"><button class="primary" data-action="hear-letter">♪ Hear the letter</button><button class="secondary" data-action="clear-trace">Try a fresh trail</button><button class="secondary" data-action="keep-trace">Keep my drawing ↗</button></div><p id="trace-feedback" class="quiet-note" role="status">Trace for fun, not a handwriting score. Lowercase uses a visual letter guide. This activity does not change spelling progress. Drawings are temporary; use Keep my drawing to save a picture.</p></div>`;tracePaths=[];const can=$('trace-canvas'),guard=WWCreative.pointerGuard();activePointerGuard=guard;function point(e){const r=can.getBoundingClientRect();return[(e.clientX-r.left)/r.width*850,(e.clientY-r.top)/r.height*420];}can.addEventListener('pointerdown',e=>{if(!guard.begin(e))return;e.preventDefault();tracing=true;if(guard.penSeen())$('trace-feedback').textContent='Pencil guard is on. Fingers will not draw. Use Enable finger drawing to switch back.';tracePaths.push([point(e)]);can.setPointerCapture(e.pointerId);drawTrace();});can.addEventListener('pointermove',e=>{if(!tracing||!guard.move(e))return;e.preventDefault();if(tracePaths.reduce((n,p)=>n+p.length,0)>=10000){tracing=false;$('trace-feedback').textContent='This page is full of trails. Keep your drawing, then try a fresh trail.';return;}tracePaths[tracePaths.length-1].push(point(e));drawTrace();});can.addEventListener('pointerup',e=>{if(!guard.end(e))return;tracing=false;$('trace-feedback').textContent='You made your own letter trail. Take another path or choose another letter—no score needed.';});const cancelStroke=e=>{if(guard.end(e))tracing=false;};can.addEventListener('pointercancel',cancelStroke);can.addEventListener('lostpointercapture',cancelStroke);drawTrace();}
function drawTrace(){const can=$('trace-canvas');if(!can)return;const g=A.setup(can,850,420);g.fillStyle='#fbfcf1';g.fillRect(0,0,850,420);for(const y of [85,215,345]){g.setLineDash([9,8]);A.line(g,[[45,y],[805,y]],'#ccdcd0',2);}g.setLineDash([]);if(lower){g.font='320px system-ui';g.textAlign='center';g.fillStyle='#dde7d8';g.fillText(letter.toLowerCase(),425,335);}else{const paths=strokes[letter];paths.forEach((p,i)=>{A.line(g,p.map(([x,y])=>[265+x*320,25+y*390]),'#d4e3d7',28);g.setLineDash([4,13]);A.line(g,p.map(([x,y])=>[265+x*320,25+y*390]),'#83b5a0',3);g.setLineDash([]);const [x,y]=p[0];A.ellipse(g,265+x*320,25+y*390,14,14,'#4c9288');g.font='bold 13px system-ui';g.fillStyle='#fff6d5';g.textAlign='center';g.fillText(i+1,265+x*320,30+y*390);});}tracePaths.forEach(p=>A.line(g,p,'#bb8b63',12));}
