const flightAttempts=new Map(),flightTargets=new Map();
function glider(){
 const owner=profile,attempt=(flightAttempts.get(owner.id)||0)+1;flightAttempts.set(owner.id,attempt);
 const flight=WWFlight.createFlight({seed:owner.seed+owner.flights*97+attempt*7919,previous:flightTargets.get(owner.id)||[]});flightTargets.set(owner.id,flight.snapshot().targets);
 mode='glider';openModal('Star Glider','A LITTLE MOVEMENT BREAK');let credited=false;
 activityStop=WWFlight.mount($('modal-body'),{flight,art:A,motion:()=>owner.motion&&!reduced.matches,night:()=>owner.theme==='night',avatar:owner.avatar,artwork:owner.artwork,onSpeak:speak,onReplay:glider,onPaint:paintView,onHome:close,onComplete:async()=>{if(credited||profile!==owner)return false;credited=true;owner.flights++;owner.revision++;owner.updatedAt=Date.now();return await save();}});
}

