function animateMission(progress){cancelAnimationFrame(missionFrame);const start=performance.now(),can=$('mission');if(!can)return;const tick=now=>{if(!can.isConnected||document.hidden){missionFrame=requestAnimationFrame(tick);return;}const motion=profile.motion&&!reduced.matches;A.mission(can,progress===undefined?round+(resolved?1:0):progress,profile.avatar,profile.theme==='night',profile.artwork,motion?(now-start)/1000:0);if(motion)missionFrame=requestAnimationFrame(tick);};tick(start);}
async function keepPicture(picture){if(!(profile.gallery||[]).includes(picture)&&(profile.gallery||[]).length>=12)throw Error('Your gallery has 12 pictures. Download a favorite, then remove one from My picture gallery to make room.');profile.gallery=profile.gallery||[];if(!profile.gallery.includes(picture))profile.gallery.push(picture);profile.revision++;profile.updatedAt=Date.now();return await save();}
