 if(Number.isInteger(index)&&!original){toast('This picture is no longer in the gallery.');return;}
 const initial=original?JSON.parse(JSON.stringify(original)):null;
 const update=original?async picture=>{if(profile!==owner)return false;if(!original)return await keepPicture(picture);const at=owner.gallery.indexOf(original);if(at<0)throw Error('This picture changed. Keep a downloaded copy before leaving.');owner.gallery[at]=picture;original=picture;owner.revision++;owner.updatedAt=Date.now();return await save();}:undefined;
