function galleryView(){mode='gallery';openModal('My picture gallery','YOUR OWN COLORWAKE COLLECTION');const art=profile.gallery||[];$('modal-body').innerHTML='<section class="picture-gallery"><p>Pictures for '+escape(display(profile))+'. '+art.length+' / 12 saved on this device. Your progress export includes these pictures.</p><button class="primary gold" data-action="paint">Paint a picture</button><div class="gallery-grid">'+art.map((d,i)=>'<article class="gallery-card"><canvas id="gallery-'+i+'" aria-label="Saved picture '+(i+1)+'"></canvas><h3>'+escape(d.title)+'</h3><div class="learn-controls"><button class="secondary" data-action="gallery-edit" data-index="'+i+'">Edit picture '+(i+1)+'</button><button class="secondary" data-action="gallery-download" data-index="'+i+'">Download picture '+(i+1)+'</button><button class="secondary" data-action="gallery-delete" data-index="'+i+'">Remove picture '+(i+1)+'</button></div></article>').join('')+'</div>'+(!art.length?'<p>Your first masterpiece belongs here. Paint a picture, then choose Save to my gallery.</p>':'')+'</section>';art.forEach((d,i)=>WWDrawing.paint($('gallery-'+i),d.strokes,d.paper,d.layers));}
function drawAnswer(){
 if(resolved){toast('This discovery is complete. Try drawing on the next one.');return;}
 const count=subject==='math'&&['m-count','m-add10','m-sub10'].includes(q.id),host=$('drawing-answer-host');
 $('modal').classList.add('answer-modal');$('modal-body').scrollTop=0;
 if(!host.children.length){
  const feedbackHome=$('feedback').parentElement,feedbackBefore=$('feedback').nextSibling,nextHome=$('next-question').parentElement;
  const returnToChoices=()=>{feedbackHome.insertBefore($('feedback'),feedbackBefore);nextHome.append($('next-question'));$('modal').classList.remove('answer-modal');$('modal-body').scrollTop=0;document.querySelector('[data-action="draw-answer"]').focus({preventScroll:true});};
  mountPaper(host,{guided:true,count,writeNumber:count,title:subject==='math'?q.prompt:q.clue,
   instruction:count?'Count the objects. Tap one dot for each object, or choose Write number. Then check your answer.':subject==='spelling'?'Write the word, then reveal it and compare your letters.':'Draw your thinking. Return to the answer choices when you are ready.',
   onBack:returnToChoices,
   onAnswer:count?(n)=>evaluate(n):subject==='spelling'?(_n,box,button)=>{hinted=true;box.textContent='Compare your writing with: '+q.word.toUpperCase()+'. '+q.note;button.textContent='I checked my writing';button.onclick=()=>{evaluate(q.word);button.disabled=true;};}:undefined});
  const heading=host.querySelector('.paint-heading'),copy=document.createElement('div');copy.className='guided-copy';while(heading.firstChild)copy.append(heading.firstChild);heading.append(copy);
  if(subject==='math'&&q.visual&&q.visual.type!=='crystal'){const reference=document.createElement('canvas');reference.className='paint-reference';reference.setAttribute('role','img');reference.setAttribute('aria-label','Visual support for this problem');heading.append(reference);heading.classList.add('has-reference');A.visual(reference,q.visual);}
  if(subject==='spelling'){const hear=document.createElement('button');hear.className='secondary guided-hear';hear.dataset.action='hear-word';hear.textContent='♪ Hear the word';heading.append(hear);heading.classList.add('has-hear');}
  const outcome=document.createElement('div');outcome.className='answer-outcome';host.querySelector('.guided-paper').append(outcome);
  outcome.append($('feedback'));host.querySelector('.guided-paint-dock').append($('next-question'));
 }
 host.querySelector('.answer-outcome').append($('feedback'));host.querySelector('.guided-paint-dock').append($('next-question'));
 host.querySelector('.paint-heading h3').tabIndex=-1;host.querySelector('.paint-heading h3').focus({preventScroll:true});
}

